long long spec_pal_vulkan_pack_f32(long long dst_ptr, long long byte_offset, double val) {
    if (dst_ptr) {
        float f = (float)val;
        memcpy((char*)(intptr_t)dst_ptr + byte_offset, &f, 4);
    }
    return 0;
}
